const update = $input.first().json;

const callbackQuery = update.callback_query || null;

const message =
  update.message ||
  update.edited_message ||
  callbackQuery?.message ||
  {};

const from =
  callbackQuery?.from ||
  message.from ||
  {};

const chat = message.chat || {};

const document = message.document || null;
const photo = message.photo || null;

// =======================
// 1) Detect input type
// =======================

let inputType = 'text';

if (callbackQuery) {
  inputType = 'button';
} else if (document) {
  inputType = 'file';
} else if (photo) {
  // نخلي الصور file عشان أي workflow ملفات يقدر يتعامل معها
  inputType = 'file';
}

// =======================
// 2) Request ID
// =======================

const requestId = `${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;

// =======================
// 3) Text and button action
// =======================

const rawText =
  inputType === 'button'
    ? ''
    : String(message.text || message.caption || '').trim();

const buttonAction =
  inputType === 'button'
    ? String(callbackQuery.data || '').trim()
    : '';

// =======================
// 4) Normalize text/actions
// =======================

const textLower = rawText.toLowerCase().trim();
const buttonUpper = buttonAction.toUpperCase().trim();

// =======================
// 5) Global commands
// =======================

const globalCommandMap = {
  '/cancel': 'CANCEL',
  'cancel': 'CANCEL',
  'CANCEL': 'CANCEL',
  'إلغاء': 'CANCEL',
  'الغاء': 'CANCEL',

  '/menu': 'MENU',
  'menu': 'MENU',
  'MENU': 'MENU',
  'MAIN_MENU': 'MENU',
  'القائمة': 'MENU',
  'القائمة الرئيسية': 'MENU',

  '/start': 'MENU',
  'start': 'MENU',
  'START': 'MENU',

  '/reset': 'RESET',
  'reset': 'RESET',
  'RESET': 'RESET',

  '/help': 'HELP',
  'help': 'HELP',
  'HELP': 'HELP',
  'مساعدة': 'HELP'
};

let command = '';

if (globalCommandMap[textLower]) {
  command = globalCommandMap[textLower];
}

if (globalCommandMap[rawText]) {
  command = globalCommandMap[rawText];
}

if (globalCommandMap[buttonAction]) {
  command = globalCommandMap[buttonAction];
}

if (globalCommandMap[buttonUpper]) {
  command = globalCommandMap[buttonUpper];
}

const isGlobalCommand = command !== '';

// =======================
// 6) Normalize service actions
// =======================

function normalizeAction({ inputType, rawText, buttonAction, isGlobalCommand, command }) {
  const text = String(rawText || '').trim();
  const lower = text.toLowerCase();
  const btn = String(buttonAction || '').trim().toUpperCase();

  // إذا الأمر global، خلي normalized_action نفس الأمر
  if (isGlobalCommand) {
    return command || 'UNKNOWN';
  }

  // Button actions are the most reliable
  const buttonActions = {
    'START_CREATE_CV': 'CREATE_CV',
    'CREATE_CV': 'CREATE_CV',

    'START_ANALYZE_CV': 'ANALYZE_CV',
    'ANALYZE_CV': 'ANALYZE_CV',

    'START_OPTIMIZE_CV': 'OPTIMIZE_CV',
    'OPTIMIZE_CV': 'OPTIMIZE_CV',
    'GENERATE_OPTIMIZED_CV': 'OPTIMIZE_CV',
    'GENERATE_OPTIMIZED_CV_PDF': 'OPTIMIZE_CV',

    'START_MATCH_CV': 'MATCH_CV_WITH_JOB',
    'MATCH_CV': 'MATCH_CV_WITH_JOB',
    'MATCH_CV_WITH_JOB': 'MATCH_CV_WITH_JOB',

    'START_EDIT_CV': 'EDIT_CV',
    'EDIT_CV': 'EDIT_CV',

    'HELP': 'HELP',
    'MENU': 'MENU',
    'MAIN_MENU': 'MENU',
    'CANCEL': 'CANCEL'
  };

  if (inputType === 'button' && buttonActions[btn]) {
    return buttonActions[btn];
  }

  // File upload usually means analyze CV ONLY if no active session exists.
  // لاحقاً WF_00 إذا وجد active session سيعمل override للـ normalized_action.
  if (inputType === 'file') {
    return 'ANALYZE_CV';
  }

  // Text fallback mapping
  if (
    lower.includes('إنشاء') ||
    lower.includes('انشاء') ||
    lower.includes('create') ||
    lower.includes('بناء cv') ||
    lower.includes('بناء السيرة')
  ) {
    return 'CREATE_CV';
  }

  if (
    lower.includes('تحليل') ||
    lower.includes('analyze') ||
    lower.includes('ats')
  ) {
    return 'ANALYZE_CV';
  }

  if (
    lower.includes('تحسين') ||
    lower.includes('optimize') ||
    lower.includes('محسن')
  ) {
    return 'OPTIMIZE_CV';
  }

  if (
    lower.includes('مطابقة') ||
    lower.includes('match') ||
    lower.includes('وظيفة') ||
    lower.includes('job')
  ) {
    return 'MATCH_CV_WITH_JOB';
  }

  if (
    lower.includes('تعديل') ||
    lower.includes('edit')
  ) {
    return 'EDIT_CV';
  }

  if (
    lower.includes('مساعدة') ||
    lower.includes('help')
  ) {
    return 'HELP';
  }

  return 'UNKNOWN';
}

const normalizedAction = normalizeAction({
  inputType,
  rawText,
  buttonAction,
  isGlobalCommand,
  command
});

// =======================
// 7) File payload
// =======================

const file = document
  ? {
      channel_file_id: document.file_id || '',
      file_unique_id: document.file_unique_id || '',
      file_name: document.file_name || '',
      mime_type: document.mime_type || '',
      file_size: document.file_size || null,
      source: 'document'
    }
  : photo
    ? {
        channel_file_id: photo[photo.length - 1]?.file_id || '',
        file_unique_id: photo[photo.length - 1]?.file_unique_id || '',
        file_name: '',
        mime_type: 'image/jpeg',
        file_size: photo[photo.length - 1]?.file_size || null,
        source: 'photo'
      }
    : null;

// =======================
// 8) Standard request
// =======================

const standardRequest = {
  request_id: requestId,

  channel: 'telegram',

  user: {
    id: '',
    channel: 'telegram',
    channel_user_id: String(from.id || chat.id || ''),
    username: from.username || '',
    first_name: from.first_name || '',
    last_name: from.last_name || '',
    language_code: from.language_code || 'ar'
  },

  session: {
    id: '',
    status: '',
    active_service: '',
    session_type: '',
    locked: false,
    current_step: '',
    context_json: {}
  },

  input: {
    type: inputType,
    text: rawText,
    button_action: buttonAction,
    normalized_action: normalizedAction,
    file
  },

  control: {
    is_global_command: isGlobalCommand,
    command,
    should_check_active_session: !isGlobalCommand,
    should_bypass_intent_detection: false
  },

  context: {
    language: from.language_code || 'ar',
    source: 'telegram',
    timezone: 'Asia/Amman'
  },

  meta: {
    chat_id: String(chat.id || from.id || ''),
    raw_message_id: String(message.message_id || ''),
    callback_query_id: callbackQuery?.id || '',
    created_at: new Date().toISOString()
  },

  raw: update
};

return [
  {
    json: standardRequest
  }
];

const original = $("Normalize Telegram Input").first().json;
const dbUser = $input.first().json;

const merged = {
  ...original,
  user: {
    ...original.user,
    id: String(dbUser.id || ''),
    db_id: dbUser.id || '',
    channel: dbUser.channel || original.user.channel,
    channel_user_id: dbUser.channel_user_id || original.user.channel_user_id,
    username: dbUser.username || original.user.username,
    first_name: dbUser.first_name || original.user.first_name,
    last_name: dbUser.last_name || original.user.last_name,
    language_code: dbUser.language_code || original.user.language_code
  }
};

return [
  {
    json: merged
  }
];

const req = $("Attach DB User To Request").first().json;
const sessionRow = $input.first().json;

const hasActiveSession =
  Number(sessionRow.has_active_session || 0) === 1;

const activeService = sessionRow.active_service || '';

let contextJson = sessionRow.context_json || {};

if (typeof contextJson === 'string') {
  try {
    contextJson = JSON.parse(contextJson);
  } catch (e) {
    contextJson = {};
  }
}

const merged = {
  ...req,

  session: {
    ...req.session,
    id: String(sessionRow.session_id || ''),
    user_id: String(sessionRow.session_user_id || ''),
    status: sessionRow.session_status || '',
    active_service: activeService,
    session_type: activeService,
    locked: Number(sessionRow.session_locked || 0) === 1,
    current_step: sessionRow.current_step || '',
    context_json: contextJson
  },

  input: {
    ...req.input,

    // مهم جداً:
    // إذا في جلسة فعالة، تجاهل intent الجديد مثل ANALYZE_CV
    // وخلي الرسالة تروح لنفس خدمة الجلسة المفتوحة
    normalized_action: hasActiveSession
      ? activeService
      : req.input?.normalized_action
  },

  control: {
    ...req.control,
    has_active_session: hasActiveSession,
    should_bypass_intent_detection: hasActiveSession
  }
};

return [
  {
    json: merged
  }
];

const req = $("Attach DB User To Request").first().json;

const text = `
👋 أهلاً ${req.user.first_name || ''}

اختر الخدمة التي تريدها:
`.trim();

return [
  {
    json: {
      ok: true,
      request_id: req.request_id,
      chat_id: req.meta.chat_id,
      reply: {
        type: 'text',
        text,
        parse_mode: 'HTML',
        keyboard: [
          [{ text: '📄 إنشاء CV', callback_data: 'CREATE_CV' }],
          [{ text: '🔍 تحليل CV', callback_data: 'ANALYZE_CV' }],
          [{ text: '🎯 مطابقة وظيفة', callback_data: 'MATCH_CV_WITH_JOB' }],
          [{ text: '⚡ تحسين CV', callback_data: 'OPTIMIZE_CV' }],
          [{ text: '✏️ تعديل CV', callback_data: 'EDIT_CV' }],
          [{ text: '❓ مساعدة', callback_data: 'HELP' }]
        ]
      },
      meta: {
        source_workflow: 'WF_00_Channel_Gateway',
        user_id: req.user.id || '',
        session_id: req.session?.id || ''
      }
    }
  }
];

const req = $("Restore Route Plan Context").first().json;
const session = $input.first().json;

return [
  {
    json: {
      ...req,

      session: {
        ...req.session,
        id: String(session.id || ''),
        user_id: String(session.user_id || ''),
        status: session.status || '',
        active_service: session.active_service || '',
        session_type: session.active_service || '',
        locked: Number(session.locked || 0) === 1,
        current_step: session.current_step || '',
        context_json: session.context_json || {}
      },

      control: {
        ...req.control,
        has_active_session: true,
        should_bypass_intent_detection: true
      }
    }
  }
];

const item = $input.first().json;

if (item.route_plan?.response) {
  return [
    {
      json: item.route_plan.response
    }
  ];
}

return [
  {
    json: item
  }
];

const req = $input.first().json || {};

const userId = req.user?.id || req.user?.db_id;

if (!userId) {
  throw new Error(
    `Missing user id after WF_01. user=${JSON.stringify(req.user)}`
  );
}

if (!req.route_plan) {
  throw new Error(
    `Missing route_plan after WF_01. payload=${JSON.stringify(req)}`
  );
}

const contextJson = req.route_plan.context_json || {};

// تجهيز JSON للاستخدام داخل SQL بأمان نسبي
const contextJsonSql = JSON.stringify(contextJson)
  .replace(/\\/g, '\\\\')
  .replace(/'/g, "\\'");

return [
  {
    json: {
      ...req,

      user: {
        ...req.user,
        id: String(userId),
        db_id: Number(userId)
      },

      session_start: {
        should_start_service: req.route_plan.should_start_service === true,
        service: req.route_plan.active_service || req.route_plan.service || '',
        current_step: req.route_plan.current_step || req.route_plan.step || 'start',
        status: req.route_plan.status || 'active',
        locked: req.route_plan.locked === true ? 1 : 0,
        context_json: contextJson,
        context_json_sql: contextJsonSql
      }
    }
  }
];

const req = $("Cache Route Plan Context").first().json;

if (!req.user?.id) {
  throw new Error(`Missing user.id in cached route context`);
}

if (!req.session_start?.should_start_service) {
  throw new Error(`Cached route context is not a start-service request`);
}

return [
  {
    json: req
  }
];
